27	/**
28	 * Detects "possible duplicate" owners: a new owner that is not a hard duplicate (see
29	 * {@link OwnerIdentityUniquenessValidator}) but still shares an existing owner's last name
30	 * (compared case-insensitively) and postcode under a <em>different</em> telephone. The comparison is
31	 * done in memory because the stored last names are not kept in a normalized form, for the same
32	 * reason as the name matching in {@link NamesakeCounter} and the household matching in
33	 * {@link OwnerHouseholdRegistrar}.
34	 */
35	@Component
36	public class PossibleDuplicateOwnerDetector {
37	
38	    private final ClinicService clinicService;
39	
40	    public PossibleDuplicateOwnerDetector(ClinicService clinicService) {
41	        this.clinicService = clinicService;
42	    }
43	
44	    /**
45	     * Finds the existing owner the given (not-yet-saved) owner is a possible duplicate of: the
46	     * earliest owner sharing its last name (case-insensitively) and postcode but registered under a
47	     * different telephone. The owner's telephone is expected to already be in its normalized form.
48	     *
49	     * @param owner the owner being created
50	     * @return the id of the earliest matching owner, or empty when the owner is not a possible
51	     *         duplicate of any existing owner
52	     */
53	    public Optional<Integer> findPossibleDuplicateOf(Owner owner) {
54	        if (owner.getPostcode() == null) {
55	            return Optional.empty();
56	        }
57	        return this.clinicService.findAllOwners().stream()
58	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName()))
59	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
60	            .filter(existing -> !Objects.equals(existing.getTelephone(), owner.getTelephone()))
61	            .min(Comparator.comparing(Owner::getId))
62	            .map(Owner::getId);
63	    }
64	
65	    private static boolean equalsIgnoreCase(String a, String b) {
66	        return a != null && a.equalsIgnoreCase(b);
67	    }
68	}
